CREATE FUNCTION ultrabrain.invalidate_memory_policy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $f$
DECLARE target_source text;target_slug text;rec record;
BEGIN
 IF TG_OP='UPDATE' AND NEW.compiled_truth IS NOT DISTINCT FROM OLD.compiled_truth AND NEW.timeline IS NOT DISTINCT FROM OLD.timeline AND NEW.title IS NOT DISTINCT FROM OLD.title AND NEW.frontmatter IS NOT DISTINCT FROM OLD.frontmatter AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash AND NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug AND NEW.source_id IS NOT DISTINCT FROM OLD.source_id THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN target_source=NEW.source_id;target_slug=NEW.slug;ELSE target_source=OLD.source_id;target_slug=OLD.slug;END IF;
 UPDATE ultrabrain.memory_policies SET revision=revision+1,
  status=CASE WHEN status IN ('retracted','superseded') THEN status ELSE 'review_required' END,updated_at=now()
  WHERE source_id=target_source AND slug=target_slug RETURNING * INTO rec;
 IF FOUND THEN
  INSERT INTO ultrabrain.memory_policy_history(source_id,slug,revision,event_id,request_hash,actor_key,snapshot)
  VALUES(rec.source_id,rec.slug,rec.revision,'native:'||rec.revision,'native-trigger','native-trigger',
  jsonb_build_object('status',rec.status,'reason','Native source changed; review required before current recall','operation',TG_OP));
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $f$
